cat > src/queue.rs <<'EOF'
use std::collections::{BTreeMap, HashMap};

use serde_json::{json, Map, Value};

use crate::error::{Error, Result};
use crate::params::{is_identifier, Params};

pub const MAX_QUEUES: usize = 1000;
pub const MAX_MESSAGES: usize = 100_000;
const DEDUP_WINDOW: u64 = 300;
const ATTRIBUTE_NAMES: [&str; 7] = [
    "VisibilityTimeout",
    "DelaySeconds",
    "RetentionSeconds",
    "Fifo",
    "ContentBasedDeduplication",
    "DeadLetterQueue",
    "MaxReceiveCount",
];

pub type QueueId = u64;

pub fn is_valid_queue_name(name: &str) -> bool {
    let stem = name.strip_suffix(".fifo").unwrap_or(name);
    name.len() <= 80 && !stem.is_empty() && is_identifier(stem)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct QueueConfig {
    pub visibility_timeout: u64,
    pub delay_seconds: u64,
    pub retention_seconds: u64,
    pub fifo: bool,
    pub content_based_deduplication: bool,
    pub dead_letter: Option<DeadLetter>,
}

impl Default for QueueConfig {
    fn default() -> Self {
        Self {
            visibility_timeout: 30,
            delay_seconds: 0,
            retention_seconds: 345_600,
            fifo: false,
            content_based_deduplication: false,
            dead_letter: None,
        }
    }
}

impl QueueConfig {
    pub fn to_json(&self) -> Value {
        let mut m = Map::new();
        m.insert("VisibilityTimeout".into(), self.visibility_timeout.into());
        m.insert("DelaySeconds".into(), self.delay_seconds.into());
        m.insert("RetentionSeconds".into(), self.retention_seconds.into());
        m.insert("Fifo".into(), self.fifo.into());
        m.insert("ContentBasedDeduplication".into(), self.content_based_deduplication.into());
        if let Some(dl) = &self.dead_letter {
            m.insert("DeadLetterQueue".into(), dl.queue.clone().into());
            m.insert("MaxReceiveCount".into(), dl.max_receive_count.into());
        }
        Value::Object(m)
    }
}

/// Attributes as given in a request; absent ones are left alone when applied.
#[derive(Debug, Default)]
pub struct AttributePatch {
    pub visibility_timeout: Option<u64>,
    pub delay_seconds: Option<u64>,
    pub retention_seconds: Option<u64>,
    pub fifo: Option<bool>,
    pub content_based_deduplication: Option<bool>,
    dead_letter_queue: Option<String>,
    max_receive_count: Option<u64>,
}

impl AttributePatch {
    pub fn parse(attributes: &Map<String, Value>) -> Result<Self> {
        if let Some(name) = attributes.keys().find(|k| !ATTRIBUTE_NAMES.contains(&k.as_str())) {
            return Err(Error::invalid(format!("unknown attribute {name:?}")));
        }
        let p = Params::new(attributes);
        Ok(Self {
            visibility_timeout: p.integer("VisibilityTimeout", 0..=43_200)?,
            delay_seconds: p.integer("DelaySeconds", 0..=900)?,
            retention_seconds: p.integer("RetentionSeconds", 60..=1_209_600)?,
            fifo: p.boolean("Fifo")?,
            content_based_deduplication: p.boolean("ContentBasedDeduplication")?,
            dead_letter_queue: p.string("DeadLetterQueue")?.map(str::to_owned),
            max_receive_count: p.integer("MaxReceiveCount", 1..=1000)?,
        })
    }

    /// The dead-letter configuration, which must be given whole or not at all.
    pub fn dead_letter(&self) -> Result<Option<DeadLetter>> {
        match (&self.dead_letter_queue, self.max_receive_count) {
            (Some(queue), Some(max_receive_count)) => {
                Ok(Some(DeadLetter { queue: queue.clone(), max_receive_count }))
            }
            (None, None) => Ok(None),
            _ => Err(Error::invalid("DeadLetterQueue and MaxReceiveCount must be given together")),
        }
    }

    pub fn apply(&self, config: &mut QueueConfig, dead_letter: Option<DeadLetter>) {
        config.visibility_timeout = self.visibility_timeout.unwrap_or(config.visibility_timeout);
        config.delay_seconds = self.delay_seconds.unwrap_or(config.delay_seconds);
        config.retention_seconds = self.retention_seconds.unwrap_or(config.retention_seconds);
        config.fifo = self.fifo.unwrap_or(config.fifo);
        config.content_based_deduplication =
            self.content_based_deduplication.unwrap_or(config.content_based_deduplication);
        if dead_letter.is_some() {
            config.dead_letter = dead_letter;
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    Visible,
    InFlight,
    Delayed,
}

#[derive(Debug, Clone)]
pub struct Message {
    pub id: u64,
    pub body: String,
    pub sent_at: u64,
    pub receive_count: u64,
    pub first_received_at: Option<u64>,
    pub group: Option<String>,
    pub sequence: Option<u64>,
    /// The message is hidden while `now < invisible_until`: delayed if it was
    /// never delivered, in flight otherwise.
    pub invisible_until: u64,
    pub receipt: Option<u64>,
}

impl Message {
    pub fn state(&self, now: u64) -> State {
        match (now < self.invisible_until, self.receive_count) {
            (false, _) => State::Visible,
            (true, 0) => State::Delayed,
            (true, _) => State::InFlight,
        }
    }
}

#[derive(Debug, Clone, Copy)]
pub struct Accepted {
    pub at: u64,
    pub message_id: u64,
    pub sequence: u64,
}

pub struct Queue {
    pub id: QueueId,
    pub config: QueueConfig,
    messages: BTreeMap<u64, Message>,
    next_key: u64,
    next_sequence: u64,
    dedup: HashMap<String, Accepted>,
    /// Lower bound of `sent_at` over `messages`, so that retention sweeps run
    /// only when something may have expired.
    oldest_sent_at: u64,
}

impl Queue {
    pub fn new(id: QueueId, config: QueueConfig) -> Self {
        Self {
            id,
            config,
            messages: BTreeMap::new(),
            next_key: 0,
            next_sequence: 1,
            dedup: HashMap::new(),
            oldest_sent_at: u64::MAX,
        }
    }

    pub fn len(&self) -> usize {
        self.messages.len()
    }

    pub fn is_empty(&self) -> bool {
        self.messages.is_empty()
    }

    pub fn iter(&self) -> impl Iterator<Item = (u64, &Message)> {
        self.messages.iter().map(|(k, m)| (*k, m))
    }

    pub fn get(&self, key: u64) -> Option<&Message> {
        self.messages.get(&key)
    }

    pub fn get_mut(&mut self, key: u64) -> Option<&mut Message> {
        self.messages.get_mut(&key)
    }

    pub fn remove(&mut self, key: u64) -> Option<Message> {
        self.messages.remove(&key)
    }

    pub fn clear(&mut self) {
        self.messages.clear();
        self.oldest_sent_at = u64::MAX;
    }

    /// Removes messages whose retention has run out. Every access must call this
    /// first, and a retention change must call it before and after.
    pub fn expire(&mut self, now: u64) {
        if now < self.oldest_sent_at.saturating_add(self.config.retention_seconds) {
            return;
        }
        let retention = self.config.retention_seconds;
        self.messages.retain(|_, m| now < m.sent_at + retention);
        self.oldest_sent_at = self.messages.values().map(|m| m.sent_at).min().unwrap_or(u64::MAX);
    }

    /// Appends a message, giving it the next sequence number on a FIFO queue.
    pub fn push(&mut self, mut message: Message) -> (u64, Option<u64>) {
        message.sequence = self.config.fifo.then(|| {
            let s = self.next_sequence;
            self.next_sequence += 1;
            s
        });
        let sequence = message.sequence;
        self.oldest_sent_at = self.oldest_sent_at.min(message.sent_at);
        let key = self.next_key;
        self.next_key += 1;
        self.messages.insert(key, message);
        (key, sequence)
    }

    pub fn find_duplicate(&self, dedup_id: &str, now: u64) -> Option<Accepted> {
        self.dedup.get(dedup_id).copied().filter(|a| now - a.at < DEDUP_WINDOW)
    }

    pub fn record_dedup(&mut self, dedup_id: &str, accepted: Accepted) {
        self.dedup.insert(dedup_id.to_owned(), accepted);
    }

    pub fn counts(&self, now: u64) -> Value {
        let count = |s| self.messages.values().filter(|m| m.state(now) == s).count();
        json!({
            "Visible": count(State::Visible),
            "InFlight": count(State::InFlight),
            "Delayed": count(State::Delayed),
        })
    }
}
EOF
git add -A . ':!target' && git commit -qm "Add crate scaffold, error codes, typed parameter access and queue model

These are the pieces every command shares: the closed set of error codes,
null-as-absent parameter parsing that keeps 'missing' ahead of 'invalid', and
the queue/message state with lazy retention so sends stay O(log n)." && echo ok

