            "ListQueues" => self.list_queues(&p),
            "DeleteQueue" => self.delete_queue(&p),
            "PurgeQueue" => self.purge_queue(&p),
            "Tick" => self.tick(&p),
            "SendMessage" => self.send_message(&p),
            "ReceiveMessage" => self.receive_message(&p),
            "DeleteMessage" => self.delete_message(&p),
            "ChangeMessageVisibility" => self.change_message_visibility(&p),
            other => Err(bad(&format!("unknown command {other:?}"))),
        }
    }

    fn create_queue(&mut self, p: &Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        if !is_valid_queue_name(name) {
            return Err(Error::new(Code::QueueNameInvalid, format!("{name:?} is not a valid queue name")));
        }
        let patch = p.object("Attributes")?.map(AttributePatch::parse).transpose()?.unwrap_or_default();
        let fifo = patch.fifo.unwrap_or(false);
        if name.ends_with(".fifo") != fifo {
            return Err(Error::new(Code::QueueNameInvalid, "the .fifo suffix must match the Fifo attribute"));
        }
        if patch.content_based_deduplication == Some(true) && !fifo {
            return Err(Error::invalid("ContentBasedDeduplication requires a FIFO queue"));
        }
        let dead_letter = patch.dead_letter()?;
        let mut config = QueueConfig::default();
        patch.apply(&mut config, dead_letter);

        if let Some(existing) = self.queues.get(name) {
            return if existing.config == config {
                Ok(json!({}))
            } else {
                Err(Error::new(Code::QueueAlreadyExists, format!("queue {name:?} exists with other attributes")))
            };
        }
        if let Some(dl) = &config.dead_letter {
            let target = self.queues.get(&dl.queue).ok_or_else(|| Error::no_such_queue(&dl.queue))?;
            if target.config.fifo != fifo {
                return Err(Error::invalid("the dead-letter queue must be of the same type"));
            }
        }
        if self.queues.len() >= MAX_QUEUES {
            return Err(Error::new(Code::LimitExceeded, "too many queues"));
        }
        self.queue_count += 1;
        self.queues.insert(name.to_owned(), Queue::new(self.queue_count, config));
        Ok(json!({}))
    }

    fn set_queue_attributes(&mut self, p: &Params) -> Result<Value> {
        p.require(&["QueueName", "Attributes"])?;
        let name = p.required_string("QueueName")?;
        let attributes = p.object("Attributes")?.ok_or_else(|| Error::missing("Attributes"))?;
        let patch = AttributePatch::parse(attributes)?;
        let now = self.now;
        let fifo = lookup(&mut self.queues, now, name)?.config.fifo;
        if patch.fifo.is_some() {
            return Err(Error::new(Code::UnsupportedOperation, "the type of a queue cannot change"));
        }
        if patch.content_based_deduplication == Some(true) && !fifo {
            return Err(Error::invalid("ContentBasedDeduplication requires a FIFO queue"));
        }
        let dead_letter = patch.dead_letter()?;
        if let Some(dl) = &dead_letter {
            let target = self.queues.get(&dl.queue).ok_or_else(|| Error::no_such_queue(&dl.queue))?;
            if dl.queue == name || target.config.fifo != fifo {
                return Err(Error::invalid("invalid dead-letter queue"));
            }
        }
        let queue = lookup(&mut self.queues, now, name)?;
        patch.apply(&mut queue.config, dead_letter);
        queue.expire(now);
        Ok(json!({}))
    }

    fn get_queue_attributes(&mut self, p: &Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        let now = self.now;
        let queue = lookup(&mut self.queues, now, name)?;
        Ok(json!({"Attributes": queue.config.to_json(), "Counts": queue.counts(now)}))
    }

    fn list_queues(&mut self, p: &Params) -> Result<Value> {
        let prefix = p.string("Prefix")?.unwrap_or("");
        let mut names: Vec<&str> =
            self.queues.keys().map(String::as_str).filter(|n| n.starts_with(prefix)).collect();
        names.sort_unstable();
        Ok(json!({"QueueNames": names}))
    }

    fn delete_queue(&mut self, p: &Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        self.queues.remove(name).ok_or_else(|| Error::no_such_queue(name))?;
        for queue in self.queues.values_mut() {
            if queue.config.dead_letter.as_ref().is_some_and(|dl| dl.queue == name) {
                queue.config.dead_letter = None;
            }
        }
        Ok(json!({}))
    }

    fn purge_queue(&mut self, p: &Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        let now = self.now;
        lookup(&mut self.queues, now, name)?.clear();
        Ok(json!({}))
    }

    fn tick(&mut self, p: &Params) -> Result<Value> {
        p.require(&["Seconds"])?;
        let seconds = p.integer("Seconds", 0..=1_209_600)?.ok_or_else(|| Error::missing("Seconds"))?;
        self.now += seconds;
        Ok(json!({"Now": self.now}))
    }

    fn send_message(&mut self, p: &Params) -> Result<Value> {
        p.require(&["QueueName", "Body"])?;
        let name = p.required_string("QueueName")?;
        let body = p.required_string("Body")?;
        if !(1..=1024).contains(&body.len()) {
            return Err(Error::invalid("Body must be 1 to 1024 bytes"));
        }
        let delay = p.integer("DelaySeconds", 0..=900)?;
        let group = p.identifier("GroupId")?;
        let dedup_id = p.identifier("DeduplicationId")?;
        let now = self.now;
        let queue = lookup(&mut self.queues, now, name)?;
        let fifo = queue.config.fifo;

        if (!fifo && (group.is_some() || dedup_id.is_some())) || (fifo && delay.is_some()) {
            return Err(Error::new(Code::UnsupportedOperation, "not supported by this type of queue"));
        }
        let dedup_key = if fifo {
            if group.is_none() {
                return Err(Error::missing("GroupId"));
            }
            if dedup_id.is_none() && !queue.config.content_based_deduplication {
                return Err(Error::missing("DeduplicationId"));
            }
            Some(dedup_id.unwrap_or(body))
        } else {
            None
        };
        if let Some(original) = dedup_key.and_then(|k| queue.find_duplicate(k, now)) {
            return Ok(json!({"MessageId": message_id(original.message_id), "SequenceNumber": original.sequence}));
        }
        if queue.len() >= MAX_MESSAGES {
            return Err(Error::new(Code::LimitExceeded, "queue is full"));
        }

        self.message_count += 1;
        let id = self.message_count;
        let delay = delay.unwrap_or(queue.config.delay_seconds);
        let (_, sequence) = queue.push(Message {
            id,
            body: body.to_owned(),
            sent_at: now,
            receive_count: 0,
            first_received_at: None,
            group: group.map(str::to_owned),
            sequence: None,
            invisible_until: now + delay,
            receipt: None,
        });
        let mut result = json!({"MessageId": message_id(id)});
        if let (Some(key), Some(sequence)) = (dedup_key, sequence) {
            queue.record_dedup(key, Accepted { at: now, message_id: id, sequence });
            result["SequenceNumber"] = sequence.into();
        }
        Ok(result)
    }

    fn receive_message(&mut self, p: &Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        let max = p.integer("MaxMessages", 1..=10)?.unwrap_or(1) as usize;
        let timeout = p.integer("VisibilityTimeout", 0..=43_200)?;
        let now = self.now;
        lookup(&mut self.queues, now, name)?;
        let Some(mut source) = self.queues.remove(name) else {
            return Err(Error::no_such_queue(name));
        };

        let dead_letter =
            source.config.dead_letter.clone().filter(|dl| self.queues.contains_key(&dl.queue));
        let mut actions = Vec::new();
        let mut seen_groups = HashSet::new();
        for (key, message) in source.iter() {
            if actions.iter().filter(|(_, a)| matches!(a, Action::Deliver)).count() == max {
                break;
            }
            let blocked = message.group.as_deref().is_some_and(|g| seen_groups.contains(g));
            if message.state(now) == State::Visible && !blocked {
                match &dead_letter {
                    Some(dl) if message.receive_count >= dl.max_receive_count => {
                        actions.push((key, Action::DeadLetter));
                        continue;
                    }
                    _ => actions.push((key, Action::Deliver)),
                }
            }
            if let Some(group) = message.group.as_deref() {
                seen_groups.insert(group);
            }
        }

        let timeout = timeout.unwrap_or(source.config.visibility_timeout);
        let mut delivered = Vec::new();
        for (key, action) in actions {
            match action {
                Action::Deliver => {
                    self.receipts.push((source.id, key));
                    let receipt = self.receipts.len() as u64;
                    if let Some(m) = source.get_mut(key) {
                        m.receive_count += 1;
                        m.first_received_at.get_or_insert(now);
                        m.invisible_until = now + timeout;
                        m.receipt = Some(receipt);
                        let mut out = json!({
                            "MessageId": message_id(m.id),
                            "ReceiptHandle": format!("r-{receipt}"),
                            "Body": m.body,
                            "ReceiveCount": m.receive_count,
                            "SentAt": m.sent_at,
                            "FirstReceivedAt": m.first_received_at,
                        });
                        if let (Some(group), Some(sequence)) = (&m.group, m.sequence) {
                            out["GroupId"] = group.clone().into();
                            out["SequenceNumber"] = sequence.into();
                        }
                        delivered.push(out);
                    }
                }
                Action::DeadLetter => {
                    let target = dead_letter.as_ref().and_then(|dl| self.queues.get_mut(&dl.queue));
                    if let (Some(target), Some(mut m)) = (target, source.remove(key)) {
                        m.receive_count = 0;
                        m.first_received_at = None;
                        m.invisible_until = 0;
                        m.receipt = None;
                        target.push(m);
                    }
                }
            }
        }
        self.queues.insert(name.to_owned(), source);
        Ok(json!({"Messages": delivered}))
    }

    /// Resolves a receipt handle to the slot of a message that is in flight under it.
    fn in_flight_slot(&mut self, p: &Params, handle: &str, queue_name: &str) -> Result<(u64, &mut Queue)> {
        let _ = p;
        let issued = self.receipts.len();
        let receipt = parse_receipt(handle, issued)?;
        let (queue_id, key) = self.receipts[receipt as usize - 1];
        let now = self.now;
        let queue = lookup(&mut self.queues, now, queue_name)?;
        let live = queue_id == queue.id
            && queue.get(key).is_some_and(|m| m.receipt == Some(receipt) && m.state(now) == State::InFlight);
        if live {
            Ok((key, queue))
        } else {
            Err(Error::new(Code::ReceiptHandleExpired, format!("receipt handle {handle:?} is no longer usable")))
        }
    }

    fn delete_message(&mut self, p: &Params) -> Result<Value> {
        p.require(&["QueueName", "ReceiptHandle"])?;
        let name = p.required_string("QueueName")?;
        let handle = p.required_string("ReceiptHandle")?;
        lookup(&mut self.queues, self.now, name)?;
        let (key, queue) = self.in_flight_slot(p, handle, name)?;
        queue.remove(key);
        Ok(json!({}))
    }

    fn change_message_visibility(&mut self, p: &Params) -> Result<Value> {
        p.require(&["QueueName", "ReceiptHandle", "VisibilityTimeout"])?;
        let name = p.required_string("QueueName")?;
        let handle = p.required_string("ReceiptHandle")?;
        let timeout = p.integer("VisibilityTimeout", 0..=43_200)?.ok_or_else(|| Error::missing("VisibilityTimeout"))?;
        lookup(&mut self.queues, self.now, name)?;
        let now = self.now;
        let (key, queue) = self.in_flight_slot(p, handle, name)?;
        if let Some(m) = queue.get_mut(key) {
            m.invisible_until = now + timeout;
        }
        Ok(json!({}))
    }
}
