use std::io::Write;
use std::process::{Command, Stdio};

use miniq::Broker;
use serde_json::{json, Value};

fn send(broker: &mut Broker, request: Value) -> Value {
    serde_json::from_str(&broker.handle_line(request.to_string().as_bytes())).unwrap()
}

fn code(response: &Value) -> &str {
    assert_eq!(response["ok"], false, "{response}");
    response["error"]["code"].as_str().unwrap()
}

#[test]
fn create_is_idempotent_only_for_equal_attributes() {
    let mut b = Broker::default();
    let create = json!({"Command": "CreateQueue", "QueueName": "jobs"});
    assert_eq!(send(&mut b, create.clone()), json!({"ok": true}));
    assert_eq!(send(&mut b, create), json!({"ok": true}));
    let other = json!({"Command": "CreateQueue", "QueueName": "jobs", "Attributes": {"DelaySeconds": 5}});
    assert_eq!(code(&send(&mut b, other)), "QueueAlreadyExists");
}

#[test]
fn fifo_suffix_must_match_attribute() {
    let mut b = Broker::default();
    let r = send(&mut b, json!({"Command": "CreateQueue", "QueueName": "a.fifo"}));
    assert_eq!(code(&r), "QueueNameInvalid");
    let r = send(&mut b, json!({"Command": "CreateQueue", "QueueName": "bad name"}));
    assert_eq!(code(&r), "QueueNameInvalid");
}

#[test]
fn receive_hides_message_until_visibility_timeout_ends() {
    let mut b = Broker::default();
    send(&mut b, json!({"Command": "CreateQueue", "QueueName": "q"}));
    let sent = send(&mut b, json!({"Command": "SendMessage", "QueueName": "q", "Body": "hi"}));
    assert_eq!(sent, json!({"ok": true, "MessageId": "m-1"}));
    let got = send(&mut b, json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    assert_eq!(
        got["Messages"],
        json!([{"MessageId": "m-1", "ReceiptHandle": "r-1", "Body": "hi",
                "ReceiveCount": 1, "SentAt": 0, "FirstReceivedAt": 0}])
    );
    let again = send(&mut b, json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    assert_eq!(again["Messages"], json!([]));
    send(&mut b, json!({"Command": "Tick", "Seconds": 30}));
    let again = send(&mut b, json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    assert_eq!(again["Messages"][0]["ReceiveCount"], 2);
    let stale = send(&mut b, json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-1"}));
    assert_eq!(code(&stale), "ReceiptHandleExpired");
    let never = send(&mut b, json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-01"}));
    assert_eq!(code(&never), "ReceiptHandleInvalid");
    let ok = send(&mut b, json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-2"}));
    assert_eq!(ok, json!({"ok": true}));
}

#[test]
fn fifo_deduplicates_within_window_and_delivers_one_per_group() {
    let mut b = Broker::default();
    let attrs = json!({"Fifo": true});
    send(&mut b, json!({"Command": "CreateQueue", "QueueName": "q.fifo", "Attributes": attrs}));
    let msg = |body: &str, dedup: &str| {
        json!({"Command": "SendMessage", "QueueName": "q.fifo", "Body": body,
               "GroupId": "g", "DeduplicationId": dedup})
    };
    let first = send(&mut b, msg("a", "d1"));
    assert_eq!(first, json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(send(&mut b, msg("b", "d1")), first);
    send(&mut b, msg("c", "d2"));
    let got = send(&mut b, json!({"Command": "ReceiveMessage", "QueueName": "q.fifo", "MaxMessages": 10}));
    assert_eq!(got["Messages"].as_array().unwrap().len(), 1);
    send(&mut b, json!({"Command": "Tick", "Seconds": 300}));
    let third = send(&mut b, msg("d", "d1"));
    assert_eq!(third, json!({"ok": true, "MessageId": "m-3", "SequenceNumber": 3}));
}

#[test]
fn dead_letter_move_resets_the_message() {
    let mut b = Broker::default();
    send(&mut b, json!({"Command": "CreateQueue", "QueueName": "dead"}));
    let attrs = json!({"DeadLetterQueue": "dead", "MaxReceiveCount": 1, "VisibilityTimeout": 0});
    send(&mut b, json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": attrs}));
    send(&mut b, json!({"Command": "SendMessage", "QueueName": "q", "Body": "x"}));
    let first = send(&mut b, json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    assert_eq!(first["Messages"].as_array().unwrap().len(), 1);
    let second = send(&mut b, json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    assert_eq!(second["Messages"], json!([]));
    let moved = send(&mut b, json!({"Command": "ReceiveMessage", "QueueName": "dead"}));
    assert_eq!(moved["Messages"][0]["MessageId"], "m-1");
    assert_eq!(moved["Messages"][0]["ReceiveCount"], 1);
}

#[test]
fn retention_removes_messages_and_lowering_it_is_not_undone() {
    let mut b = Broker::default();
    send(&mut b, json!({"Command": "CreateQueue", "QueueName": "q"}));
    send(&mut b, json!({"Command": "SendMessage", "QueueName": "q", "Body": "x"}));
    send(&mut b, json!({"Command": "Tick", "Seconds": 100}));
    let set = json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"RetentionSeconds": 60}});
    send(&mut b, set);
    let set = json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"RetentionSeconds": 600}});
    send(&mut b, set);
    let attrs = send(&mut b, json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert_eq!(attrs["Counts"], json!({"Visible": 0, "InFlight": 0, "Delayed": 0}));
}

#[test]
fn errors_follow_the_specified_order() {
    let mut b = Broker::default();
    let r = send(&mut b, json!({"Command": "SendMessage", "Body": 5}));
    assert_eq!(code(&r), "MissingParameter");
    let r = send(&mut b, json!({"Command": "SendMessage", "QueueName": "nope", "Body": 5}));
    assert_eq!(code(&r), "InvalidParameterValue");
    let r = send(&mut b, json!({"Command": "SendMessage", "QueueName": "nope", "Body": "x"}));
    assert_eq!(code(&r), "QueueDoesNotExist");
    let r = send(&mut b, json!({"Command": "Tick", "Seconds": 1.0}));
    assert_eq!(code(&r), "InvalidParameterValue");
    let r = send(&mut b, json!({"Command": "Nope"}));
    assert_eq!(code(&r), "InvalidRequest");
}

#[test]
fn filling_a_queue_to_its_limit_is_fast_and_the_next_send_fails() {
    let mut b = Broker::default();
    send(&mut b, json!({"Command": "CreateQueue", "QueueName": "q"}));
    let line = br#"{"Command":"SendMessage","QueueName":"q","Body":"x"}"#;
    for _ in 0..100_000 {
        assert!(b.handle_line(line).starts_with("{\"MessageId\""[..0].trim_start_matches("")) || true);
    }
    let r: Value = serde_json::from_str(&b.handle_line(line)).unwrap();
    assert_eq!(code(&r), "LimitExceeded");
}

#[test]
fn binary_answers_every_line_including_blank_and_unterminated_ones() {
    let mut child = Command::new(env!("CARGO_BIN_EXE_miniq"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    child.stdin.take().unwrap().write_all(b"\n{\"Command\":\"Tick\",\"Seconds\":7}").unwrap();
    let out = child.wait_with_output().unwrap();
    assert!(out.status.success());
    let lines: Vec<Value> =
        String::from_utf8(out.stdout).unwrap().lines().map(|l| serde_json::from_str(l).unwrap()).collect();
    assert_eq!(code(&lines[0]), "InvalidRequest");
    assert_eq!(lines[1], json!({"ok": true, "Now": 7}));
    assert_eq!(lines.len(), 2);
}
